(async () => {
  const pages = figma.root.children;
  let result = [];
  for (const page of pages) {
    await page.loadAsync();
    let textNodes = page.findAll(n => n.type === 'TEXT');
    let pageSummary = {
      name: page.name,
      id: page.id,
      texts: textNodes.map(t => ({ id: t.id, name: t.name, characters: t.characters }))
    };
    result.push(pageSummary);
  }
  return result;
})()

(async () => {
  const mediaPage = figma.root.children.find(p => p.name.includes('04 · Media'));
  const compPage = figma.root.children.find(p => p.name.includes('02 · Components'));

  await mediaPage.loadAsync();
  await compPage.loadAsync();

  const getNodes = (page) => {
    return page.findAll(n => n.type === 'COMPONENT' || n.type === 'COMPONENT_SET' || n.type === 'FRAME' || n.type === 'GROUP').map(n => ({
      id: n.id,
      name: n.name,
      type: n.type,
      width: n.width,
      height: n.height
    }));
  };

  return {
    media: getNodes(mediaPage),
    components: getNodes(compPage)
  };
})()

